+    Fail() << "xLen " << xLen << ">" << limit << '\n';
+  }
+  if (x[limit]) {
+    Fail() << "x[" << limit << "]='" << x[limit] << "'\n";
+    x[limit] = '\0';
+  }
+  if (std::memcmp(x, "abcDE   ", limit)) {
+    Fail() << "x = '" << x << "'\n";
+  }
+}
